          "title": "财政部将发行3000亿元特别国债支持8家中央金融企业补充核心一级资本",
          "brief": "9月6日，财政部宣布将于近期发行3000亿元特别国债，支持中国工商银行、中国农业银行、中国进出口银行、中国出口信用保险公司、中国人保、中国人寿、中国太平、中国再保险等8家中央金融企业补充核心一级资本。根据8家企业9月6日发布的增资公告，农行拟获1300亿元、工行700亿元、进出口银行300亿元、中信保100亿元、中国人寿350亿元、人保不超过150亿元、中国太平70亿元、中国再保险30亿元特别国债资金支持；8家合计计划募资3600亿元。这是继2025年发行5000亿元特别国债注资中行、建行、交行、邮储4家国有大行后，国家再次通过特别国债为中央金融企业补充核心一级资本，覆盖国有大行、政策性金融机构和国有商业保险公司三类，按市场化、法治化原则推进。",
          "point": "【时间】2026年9月6日财政部宣布；【规模】发行3000亿元特别国债，支持8家中央金融企业补充核心一级资本；【8家分配】农行1300亿、工行700亿、进出口银行300亿、中信保100亿、中国人寿350亿、人保≤150亿、中国太平70亿、中国再保险30亿（合计计划募资3600亿，财政部拟认购上限3000亿）；【类型】国有大型商业银行（工行、农行）2家+政策性金融机构（进出口银行、中信保）2家+国有商业保险公司（中国人寿、人保、太平、中再）4家；【延续】继2025年5000亿注资中行、建行、交行、邮储4家国有大行后第二次；【核心概念】核心一级资本是金融机构抵御风险的“压舱石”；【定位】“未雨绸缪”的前瞻性、系统性安排，增强防风险与服务实体经济能力，助力金融强国建设。易考角度：特别国债、核心一级资本、金融强国/服务实体经济是宏观经济与金融时政绝对重点；“3000亿”“8家”“三类机构”数字与分类易考。"
