          "point": "【时间】2026年9月4日教育部新闻发布会；【举措】实施“教师发展国家行动”，四大发力方向：精神引领（立德树人、教育家精神、师德失范零容忍）、培养质量（试点国家卓越教师学院、人工智能+教师发展、教师AI素养全覆盖培训、国培计划改革）、公平发展（县中教师固本提质行动、国门学校优秀青年教师培养支持计划、组团式帮扶/银龄讲学/教师轮岗）、关心关爱（绩效向教学一线班主任乡村教师倾斜、尊师惠师）；【数字】全国共有1870万名人民教师；【定位】教育强国、高水平教师队伍建设。易考角度：教师队伍建设、教育家精神、教育强国是教育时政绝对重点；「四方面发力」「国家卓越教师学院」「AI+教师发展」「1870万教师」易考。"
