          "brief": "9月4日，国务院新闻办公室举行“开局起步‘十五五’”系列主题新闻发布会，介绍推进医保高质量发展有关情况。国家医保局介绍，长期护理保险参保人数已超过3.2亿，基金累计支出1142亿元，为超过460万失能人员提供了护理服务；截至目前22个省份已印发省级实施方案，建制统筹地区达到121个，预计今年底全国统筹地区将拓展至247个；按照“十五五”规划纲要部署，到2028年底长护险制度将在全国基本全面覆盖。生育保险参保人数达2.6亿，28个省份303个统筹地区实施政策范围内住院分娩个人“无自付”，所有省份将适宜辅助生殖技术纳入医保支付范围，全面实现分娩镇痛纳入医保报销。",
