          "brief": "商务部9月3日发布数据：今年1至7月，我国服务进出口总额44467.1亿元，同比增长8.3%。其中出口17732.3亿元、增长17.1%，进口26734.8亿元、增长3.2%；服务贸易逆差9002.5亿元，同比缩小1763.3亿元。旅行和运输服务出口对整体服务出口增长贡献率超50%（分别为22.1%和29.9%），知识密集型服务出口占服务出口额53.5%。",
