          "brief": "8月26日10时30分许，因尼泊尔一侧发生泥石流灾害，造成西藏日喀则市吉隆县吉隆口岸重大人员伤亡、失联。灾害发生后，中共中央总书记、国家主席、中央军委主席习近平高度重视并作出重要指示，强调当务之急要千方百计搜救失联人员，转移安置受威胁群众，抓紧救治伤员，最大限度减少人员伤亡；加强监测预警，注重科学施救，防止发生次生灾害。习近平强调，当前正处防汛关键期，各地区和有关部门要坚持极限思维、底线思维，认真落实防汛防台风各项措施，加强各类风险隐患排查整治，坚决防范重特大灾害事故发生，确保人民群众生命财产安全。李强作出批示。张国清率有关部门赶赴现场指导救援。",
