          "title": "《煤炭工业发展\"十五五\"规划》印发：到2030年大型现代化煤矿产能比重提升至87%",
          "brief": "国家发展改革委、国家能源局8月10日联合印发《煤炭工业发展\"十五五\"规划》（发改能源〔2026〕979号）。规划提出到2030年，全国大型现代化煤矿产能比重提升至87%，智能化煤矿产能比例提升至75%，煤炭消费实现达峰，煤层气产量达260亿立方米、瓦斯利用量65亿立方米；扎实推进产能储备制度，到2030年建成煤炭产能储备1亿吨/年以上。\"十四五\"时期全国煤矿数量已减至4000处左右、大型煤矿产能占85%、煤炭产量48.5亿吨。规划部署九方面重点任务，明确持续推进山西、蒙西、蒙东、陕北、新疆五大煤炭供应保障基地建设，2030年五大基地产量占全国比重超80%。",
