          "brief": "央视新闻8月9日报道，今年以来我国算力底座进一步夯实，国家超算互联网郑州核心节点首个全国产10万卡人工智能超集群正式投用，标志我国算力基础设施建设迈入10万卡级部署新阶段；“东数西算”粤港澳大湾区国家枢纽节点新国产化超节点万卡集群启用。截至6月底，全国智慧算力规模达每秒2185百亿亿次浮点运算（E FLOPS），同比增长177%；国家级算力资源调度大通道“深贵线”（深圳—贵州）加快落地。",
          "point": "考点（科技/新质生产力/数字经济）：①节点——国家超算互联网郑州核心节点、首个全国产10万卡AI超集群投用，标志迈入10万卡级部署新阶段；②数据——截至6月底全国智慧算力规模同比+177%、达2185百亿亿次浮点运算/秒；③工程——“东数西算”粤港澳枢纽万卡集群、“深贵线”国家级算力调度大通道（光直连、低时延）加快落地；④定位——全国一体化算力网、算力资源统一监测调度，服务大模型训练（万亿参数训练时间从1年压至半年），发展新质生产力重要底座；⑤衔接——人工智能+、数字经济、新基建同属科技自立自强叙事。申论科技+区情高频。"
