          "point": "考点（民生/医疗/健康中国）：①时间——三部门发布《国家基本药物目录（2026年版）》，2026年9月1日起施行；②数字——共794种（原685+109），化药生物制品476+中成药318，新增116种、调出2种；③亮点——首次将创新药纳入遴选调整范围（16种创新药、含4种国产Ⅰ类新药）、新增儿童适宜品种31种；④定位——国家基本药物制度（与基本医疗卫生制度、医保制度协同发展），保基本、强基层、惠民生，使用量占公立医疗机构71%；⑤衔接——健康中国战略、医保目录协同（新增均为医保药品）。公基+申论民生高频。"
