          "brief": "8月7日晚，北京市住建委、市规自委、北京住房公积金管理中心联合印发《关于进一步优化调整本市房地产政策的通知》：非京籍家庭购买五环内商品住房的社保或个税缴纳年限由“2年”调减为“1年”；调整后非京籍家庭在全市范围购商品房社保或个税年限统一为“1年”，五环外不限购买套数，多子女家庭五环内可再多购1套。",
