          "title": "新华社时评：中央政治局会议部署下半年经济工作，明确“宏观政策要发力提效”",
          "brief": "新华社8月6日播发时评《“发力提效”释放鲜明政策信号》指出，近日召开的中共中央政治局会议在部署下半年经济工作时，明确提出“宏观政策要发力提效”“实施好更加积极的财政政策和适度宽松的货币政策”“加大逆周期调节力度”。上半年国内生产总值同比增长4.7%，以高端制造、数字经济、现代服务为代表的新动能对经济增长贡献率超四成。会议要求存量增量政策并举，发行超长期特别国债支持“两重”“两新”，创新和优化多项结构性货币政策举措；强调优化财政金融协同促内需、强化政策落地打通“最后一公里”、加强横向协同与预期引导。",
