          "brief": "8月6日，最高人民法院举行新闻发布会，发布《关于适用〈中华人民共和国生态环境法典〉时间效力的若干规定》（以下简称《时间效力规定》），这是生态环境法典诞生后首个配套司法解释，将于2026年8月15日与法典同步施行。《时间效力规定》共13条，严格遵循立法法第104条规定的法不溯及既往原则和有利溯及例外规则，明确生态环境案件新旧法律衔接适用的一般标准和具体规则。同时，最高法对生态环境领域26件司法解释、35件司法规范性文件、45件指导性案例进行集中清理。",
          "point": "考点：①文件——《最高人民法院关于适用〈中华人民共和国生态环境法典〉时间效力的若干规定》（首个配套司法解释）；②数字——共13条、2026年8月15日与生态环境法典同步施行；③原则——立法法第104条“法不溯及既往”+有利溯及例外，以引起生态环境案件的法律事实发生时间为准；④衔接——生态环境法典8月15日施行（5编1242条、世界首部“生态环境”命名法典）；⑤清理——26件司法解释/35件司法规范性文件/45件指导性案例集中清理（保留15件、修改11件、废止试点办法、4件指导性案例不再参照）。法治/法典考点。"
