          "brief": "8月5日，财政部第三次续发行2026年超长期特别国债（四期）。本次续发行国债为30年期固定利率附息债，总额730亿元，票面利率与之前发行的同期国债相同，为2.23%。招标于8月5日10:35—11:35进行，8月6—9日分销，8月10日起合并上市交易；起息日2026年6月25日、按半年付息，2056年6月25日偿还本金并支付最后一次利息。同日，财政部还在香港发行2026年第四期150亿元人民币国债（认购倍数4.67倍）。",
