          "title": "河南出台带薪休假新政：领导干部带头、全员应休尽休、未休按日工资300%支付",
          "brief": "近日，河南省委组织部等六部门联合印发《关于进一步推动落实职工带薪错峰休假的通知》，要求领导干部带头休假，推动全员应休尽休、休满休足；确因工作需要无法安排休假的，按职工日工资收入300%支付未休年休假报酬。凡连续工作满12个月职工，不分编制、合同、劳务派遣或临时用工，均平等享受带薪年休假（满1年不满10年5天、满10年不满20年10天、满20年以上15天），鼓励“周五半天+周末+年假”短途度假模式，并对违规克扣休假权益单位追责。",
          "point": "考点（法律/民生）：①文件——河南省委组织部等六部门《关于进一步推动落实职工带薪错峰休假的通知》；②核心——领导干部带头休假、全员应休尽休、未休按日工资300%支付报酬；③法律依据——《职工带薪年休假条例》（2008年施行）第五条：经职工同意不安排休假的按日工资300%支付；④天数——满1年不满10年5天、满10年不满20年10天、满20年以上15天，法定节假日等不计入；⑤衔接——2025年中办国办《提振消费专项行动方案》要求保障休息休假权益、增强制度刚性，与扩大消费政策联动。劳动权益/公基常识高频考。"
