          "brief": "7月初至8月底的2026年全国暑期文化和旅游消费季正持续推进。文化和旅游部协同多部门、企业、平台推出惠民措施，各地围绕消夏避暑、夜间经济、研学旅行、博物馆游等热点，举办超3万场次文旅消费活动，发放超4.5亿元消费券等消费补贴。8月6日经济日报评论指出，文旅消费链条长、乘数效应大，据测算每1元文旅消费券可撬动3—5元新增消费。",
