          "brief": "7月17日，重庆彭水县汉葭街道发生山体崩塌，造成重大人员伤亡。为落实习近平总书记重要指示和李强总理等中央领导同志批示要求，根据有关法律法规，国务院成立调查评估组，由应急管理部牵头，自然资源部、公安部、住房和城乡建设部、交通运输部、中国气象局和重庆市政府等参加，对灾害进行调查评估。8月4日，调查评估组在彭水召开第一次全体会议，组长由应急管理部党委委员、中国地震局局长王昆担任。",
          "point": "考点：①定性——特别重大山体崩塌灾害，时间2026年7月17日、地点重庆彭水县汉葭街道；②调查评估组——国务院成立，应急管理部牵头，自然资源部、公安部、住建部、交通运输部、中国气象局和重庆市政府参加；③组长——王昆（应急管理部党委委员、中国地震局局长）；④原则——“科学严谨、依法依规、实事求是、注重实效”；⑤衔接——同期《全国地质灾害防治“十五五”实施方案》印发，“十五五”划定21个地质灾害重点防治区；当前正值“七下八上”防汛关键期。应急管理/防灾减灾高频考。"
